<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- formatFeticheBerryStatHintHtml builds spans from numeric stats */
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { ui as modalUi } from '../stores/ui.svelte.ts';
  import { miltankFarmTooltipHandlers, touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { game } from '../../gameManager.ts';
  import {
    formatFeticheBerryStatHint,
    formatFeticheBerryStatHintHtml,
    getFeticheBerryStatEffect,
  } from '../../constants/balance/feticheBerries.ts';
  import {
    buildBerryTreeBerryTooltipContent,
    type FeticheBerryTooltipUi,
  } from '../lib/feticheBerryTooltip.ts';
  import type { BerryTreeAlmanacEntrySnapshot, BerryTreeCombineEligibleItemSnapshot, BerryTreeMulchOptionSnapshot, BerryTreePlantOptionSnapshot } from '../bus/snapshots.js';

  let snap = $derived(miltankFarm.snapshot);
  let bt = $derived(snap.berryTree);
  let ui = $derived(bt.ui);
  let activeTab = $state<'discover' | 'almanac' | 'tree'>('discover');
  let pickerOverride = $state<number | null>(null);
  let pickerDismissed = $state(false);
  let pickerQuery = $state('');
  let pickerFilter = $state<'all' | 'evolution_stones' | 'combat' | 'other'>('all');
  let berryModalWasOpen = false;
  let queueDraftMode = $derived(bt.combineInProgress && bt.showCombinePickerDuringProgress);
  let draftSlotsEditable = $derived(!bt.combineInProgress || bt.showCombinePickerDuringProgress);
  let pickerSlotIndex = $derived.by(() => {
    if (activeTab !== 'discover' || !draftSlotsEditable) return null;
    if (pickerOverride !== null) return pickerOverride;
    if (pickerDismissed) return null;
    const next = bt.combineDraft.findIndex((slot) => !slot.itemKey);
    return next >= 0 ? next : null;
  });

  $effect(() => {
    const open = modalUi.openModals.has('berryTreeModal');
    if (open && !berryModalWasOpen) {
      activeTab = bt.unlockedCount > 0 ? 'tree' : 'discover';
    }
    berryModalWasOpen = open;
  });

  function openPicker(slotIndex: number) {
    if (!draftSlotsEditable) return;
    pickerDismissed = false;
    pickerOverride = slotIndex;
  }

  function closePicker() {
    pickerOverride = null;
    pickerQuery = '';
    pickerDismissed = true;
  }

  /** Advance to the next empty slot, using the slot index baked into the clicked tile. */
  function afterPickSlot(event: MouseEvent) {
    const arg = (event.currentTarget as HTMLElement | null)?.getAttribute('data-arg') ?? '';
    const current = Math.floor(Number(arg.split(':')[0]));
    if (!Number.isFinite(current)) return;
    const nextEmpty = bt.combineDraft.findIndex((slot, index) => index !== current && !slot.itemKey);
    pickerDismissed = false;
    pickerOverride = nextEmpty >= 0 ? nextEmpty : null;
  }

  let queueRemainingSlots = $derived(
    bt.combineQueueLevel > 0
      ? Math.max(0, bt.combineMaxInFlight - bt.combineInFlightCount)
      : 0,
  );

  let plantQueueRemainingSlots = $derived(
    bt.plantQueueLevel > 0
      ? Math.max(0, bt.plantQueueLevel - bt.plantQueuePreview.length)
      : 0,
  );

  function purchaseCombineQueueUpgrade() {
    game?.purchaseBerryCombineQueueUpgrade();
  }

  function purchasePlantQueueUpgrade() {
    game?.purchaseBerryPlantQueueUpgrade();
  }

  const TASTE_MARK: Record<string, string> = {
    loved: '♥♥',
    liked: '♥',
    neutral: '–',
    disliked: '✕',
    hated: '✕✕',
  };

  function tasteMark(taste: string | null): string | null {
    if (!taste) return null;
    return TASTE_MARK[taste] ?? null;
  }

  function tasteLabel(taste: string | null): string | null {
    if (!taste) return null;
    const labels: Record<string, string> = {
      loved: ui.tasteLoved,
      liked: ui.tasteLiked,
      neutral: ui.tasteNeutral,
      disliked: ui.tasteDisliked,
      hated: ui.tasteHated,
    };
    return labels[taste] ?? null;
  }

  function itemTip(title: string, body = '') {
    if (!title) return {};
    return touchTooltipHandlers(() => ({ title, body }));
  }

  function revealedHintCount(entry: BerryTreeAlmanacEntrySnapshot): number {
    return entry.recipeSlots.filter((slot) => slot.revealed).length;
  }

  let almanacFilter = $state<'progress' | 'unlocked'>('progress');
  let almanacChoseDefault = $state(false);
  let tasteFilter = $state<string | null>(null);

  function showAlmanac(filter?: 'progress' | 'unlocked'): void {
    if (filter) {
      almanacFilter = filter;
      almanacChoseDefault = true;
    } else if (!almanacChoseDefault) {
      almanacChoseDefault = true;
      almanacFilter = almanacCounts.progress > 0 ? 'progress' : 'unlocked';
    }
    activeTab = 'almanac';
  }

  let tasteLegend = $derived([
    { taste: 'loved', mark: '♥♥', label: ui.tasteLoved },
    { taste: 'liked', mark: '♥', label: ui.tasteLiked },
    { taste: 'neutral', mark: '–', label: ui.tasteNeutral },
    { taste: 'disliked', mark: '✕', label: ui.tasteDisliked },
    { taste: 'hated', mark: '✕✕', label: ui.tasteHated },
  ]);

  function almanacGroup(entry: BerryTreeAlmanacEntrySnapshot): 'progress' | 'unlocked' | 'other' {
    if (entry.unlocked) return 'unlocked';
    const revealed = revealedHintCount(entry);
    const total = entry.recipeSlots.length;
    if (revealed > 0 && revealed < total) return 'progress';
    return 'other';
  }

  let almanacSorted = $derived.by(() => {
    const rank = { progress: 0, unlocked: 1, other: 2 } as const;
    return [...bt.almanacEntries].sort((a, b) => {
      const groupDiff = rank[almanacGroup(a)] - rank[almanacGroup(b)];
      if (groupDiff !== 0) return groupDiff;
      if (almanacGroup(a) !== 'progress') return 0;
      const missingA = a.recipeSlots.length - revealedHintCount(a);
      const missingB = b.recipeSlots.length - revealedHintCount(b);
      return missingA - missingB;
    });
  });

  let almanacVisible = $derived(
    almanacSorted.filter((entry) => {
      if (almanacGroup(entry) !== almanacFilter) return false;
      if (tasteFilter && entry.feticheTaste !== tasteFilter) return false;
      return true;
    }),
  );

  let almanacCounts = $derived.by(() => {
    const counts = { progress: 0, unlocked: 0 };
    for (const entry of almanacSorted) {
      const group = almanacGroup(entry);
      if (group === 'progress' || group === 'unlocked') counts[group] += 1;
    }
    return counts;
  });

  let visibleHistory = $derived(
    bt.lastCombineResult
      ? bt.combineHistory.filter((entry) => entry.timestamp !== bt.lastCombineResult?.timestamp)
      : bt.combineHistory,
  );

  function useKnownHints(entry: BerryTreeAlmanacEntrySnapshot): void {
    const slots = [0, 1, 2].map((index) => {
      const slot = entry.recipeSlots[index];
      return slot?.revealed && slot.itemKey ? slot.itemKey : '';
    });
    game?.loadBerryCombineDraft(slots.join(':'));
    activeTab = 'discover';
    pickerQuery = '';
    pickerOverride = null;
    pickerDismissed = true;
  }

  let pickerQueryNormalized = $derived(pickerQuery.trim().toLocaleLowerCase());
  let pickerCategoryFlags = $derived.by(() => {
    const categories = new Set(bt.combineEligibleItemGroups.map((group) => group.category));
    return {
      evo: categories.has('evolution_stones'),
      combat: categories.has('combat'),
      other: [...categories].some((category) => category !== 'evolution_stones' && category !== 'combat'),
    };
  });
  let filteredPickerItems = $derived.by(() => {
    const items: BerryTreeCombineEligibleItemSnapshot[] = [];
    for (const group of bt.combineEligibleItemGroups) {
      if (pickerFilter === 'evolution_stones' && group.category !== 'evolution_stones') continue;
      if (pickerFilter === 'combat' && group.category !== 'combat') continue;
      if (pickerFilter === 'other' && (group.category === 'evolution_stones' || group.category === 'combat')) continue;
      for (const item of group.items) {
        if (pickerQueryNormalized && !item.displayName.toLocaleLowerCase().includes(pickerQueryNormalized)) continue;
        items.push(item);
      }
    }
    return items;
  });

  function draftHasItem(itemKey: string): boolean {
    return bt.combineDraft.some((slot) => slot.itemKey === itemKey);
  }

  function itemCompletesFailedTrio(itemKey: string): boolean {
    if (pickerSlotIndex === null) return false;
    const keys = bt.combineDraft.map((slot) => slot.itemKey ?? '');
    keys[pickerSlotIndex] = itemKey;
    if (keys.some((key) => !key)) return false;
    return bt.failedCombineKeys.includes(keys.join('|'));
  }

  function itemInFailedTrio(itemKey: string): boolean {
    return bt.failedCombineKeys.some((key) => key.split('|').includes(itemKey));
  }

  function lastResultSummary(): string {
    const result = bt.lastCombineResult;
    if (!result || result.outcomeType === 'none') return ui.lastResultFailed;
    if (result.newlyUnlockedBerries.length > 0) {
      return result.newlyUnlockedBerries.map((berry) => berry.name).join(', ');
    }
    const names = [...new Set(result.newlyRevealedHints.map((hint) => hint.berryName).filter(Boolean))];
    return names.length > 0 ? names.join(', ') : ui.lastResultRevealed;
  }

  let harvestReady = $derived(bt.canClaim || !!bt.activeCrop?.productionComplete);
  let analysisReady = $derived(!!bt.lastCombineResult);

  const tasteUi = $derived({
    tasteLoved: ui.tasteLoved,
    tasteLiked: ui.tasteLiked,
    tasteNeutral: ui.tasteNeutral,
    tasteDisliked: ui.tasteDisliked,
    tasteHated: ui.tasteHated,
    tasteCombatHint: ui.tasteCombatHint,
  } satisfies FeticheBerryTooltipUi);

  function berryTooltipHandlers(
    entry: Pick<
      BerryTreeAlmanacEntrySnapshot | BerryTreePlantOptionSnapshot,
      'feticheTaste' | 'feticheStatEffect' | 'berryDescription'
    > & { name: string },
  ) {
    return miltankFarmTooltipHandlers(() => {
      const content = buildBerryTreeBerryTooltipContent(
        {
          name: entry.name,
          feticheTaste: entry.feticheTaste,
          feticheStatEffect: entry.feticheStatEffect,
          description: entry.berryDescription,
        },
        tasteUi,
      );
      return content ?? { title: entry.name, body: '' };
    });
  }

  function mulchTooltipHandlers(mulch: BerryTreeMulchOptionSnapshot) {
    return miltankFarmTooltipHandlers(() => ({
      title: mulch.tooltipTitle,
      body: mulch.tooltipBody,
    }));
  }

  /** Hover tooltip only. The tap handler stops propagation and would swallow data-action. */
  function mulchHoverTooltip(mulch: BerryTreeMulchOptionSnapshot) {
    const handlers = mulchTooltipHandlers(mulch);
    return {
      onmouseenter: handlers.onmouseenter,
      onmouseleave: handlers.onmouseleave,
      onfocus: handlers.onfocus,
      onblur: handlers.onblur,
    };
  }

  function statHintHtml(
    effect: BerryTreeAlmanacEntrySnapshot['feticheStatEffect'],
  ): string {
    if (!effect) return '';
    return formatFeticheBerryStatHintHtml(effect);
  }

  function berryShortName(name: string): string {
    const short = name.replace(/^Baie\s+/i, '').replace(/\s+Berry$/i, '').trim();
    return short || name;
  }

  function statHintTitle(opt: BerryTreePlantOptionSnapshot): string | undefined {
    const effect = opt.feticheStatEffect;
    if (!effect) return undefined;
    const hasZero = Object.values(effect).some((value) => (Number(value) || 0) === 0);
    if (!hasZero) return undefined;
    const base = formatFeticheBerryStatHint(getFeticheBerryStatEffect(opt.berryKey));
    if (!base) return undefined;
    const taste = tasteLabel(opt.feticheTaste);
    return taste ? `${taste} · ${base}` : base;
  }

  function plantQueueSlotTitle(): string {
    const checks = bt.plantQueueChecks;
    if (checks) return `${checks.farmLabel} · ${checks.milkLabel}`;
    return ui.plantQueueUpgradeDesc;
  }

  function combineQueueSlotTitle(): string {
    const checks = bt.combineQueueChecks;
    if (checks) return `${checks.farmLabel} · ${checks.milkLabel}`;
    return ui.combineQueueUpgradeDesc;
  }
</script>

<div
  class={['stats-content', 'berry-tree-modal-content', 'miltank-farm-modal-shell', activeTab === 'almanac' && 'is-almanac']}
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header">
    <h2 id="berryTreeTitleLabel">{ui.title}</h2>
    <button type="button" class="stats-close" data-action="closeBerryTreeModal">&#10005;</button>
  </div>

  <div class="berry-tree-tabs" role="tablist">
    <button
      type="button"
      id="berryTreeTreeTab"
      class="berry-tree-tab"
      class:active={activeTab === 'tree'}
      role="tab"
      aria-selected={activeTab === 'tree'}
      title={harvestReady ? ui.productionDone : undefined}
      onclick={() => { activeTab = 'tree'; }}
    >
      {ui.tabTree}
      {#if harvestReady}<span class="berry-tree-tab-dot berry-tree-tab-dot--ready" aria-hidden="true"></span>{/if}
    </button>
    <button
      type="button"
      id="berryTreeDiscoverTab"
      class="berry-tree-tab"
      class:active={activeTab === 'discover'}
      role="tab"
      aria-selected={activeTab === 'discover'}
      title={analysisReady ? ui.lastResultTitle : undefined}
      onclick={() => { activeTab = 'discover'; }}
    >
      {ui.tabDiscover}
      {#if analysisReady}<span class="berry-tree-tab-dot berry-tree-tab-dot--analysis" aria-hidden="true"></span>{/if}
    </button>
    <button
      type="button"
      class="berry-tree-tab"
      class:active={activeTab === 'almanac'}
      role="tab"
      aria-selected={activeTab === 'almanac'}
      onclick={() => showAlmanac()}
    >{ui.tabAlmanac}</button>
  </div>

  {#if activeTab === 'discover'}
    <section class="berry-tree-panel" aria-label={ui.tabDiscover}>
      {#if bt.lastCombineResult}
        <div class={['berry-tree-last-result-banner', `result-${bt.lastCombineResult.outcomeType}`]}>
          <div class="berry-tree-mini-slots">
            {#each bt.lastCombineResult.submittedSlots as slot (slot.slotIndex)}
              {#if slot.itemIconUrl}
                <img
                  src={slot.itemIconUrl}
                  alt={slot.itemName ?? ''}
                  class="berry-tree-mini-slot-img"
                  width="22"
                  height="22"
                  {...itemTip(slot.itemName ?? '')}
                />
              {:else}
                <span class="berry-tree-mini-slot-empty">?</span>
              {/if}
            {/each}
          </div>
          <span class="berry-tree-last-result-text" title={lastResultSummary()}>{lastResultSummary()}</span>
          {#if bt.lastCombineResult.outcomeType !== 'none'}
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--reroll"
              onclick={() => showAlmanac('unlocked')}
            >{ui.viewInDexBtn}</button>
          {/if}
          <button
            type="button"
            class="berry-tree-last-result-dismiss"
            data-action="dismissBerryLastCombineResult"
            title={ui.dismissResultBtn || 'Fermer'}
            aria-label={ui.dismissResultBtn || 'Fermer'}
          >✕</button>
        </div>
      {/if}

      <div class="berry-tree-discover-layout">
        <div class="berry-tree-discover-lab">
          {#if draftSlotsEditable}
            <h3 class="berry-tree-subtitle">{queueDraftMode ? ui.combineQueueDraftTitle : ui.combineDiscoverTitle}</h3>
            <p class="berry-tree-hint">{queueDraftMode ? ui.combineQueueDraftHint : ui.pickItem}</p>
            <div class="berry-tree-combine-slots">
              {#each bt.combineDraft as slot (slot.slotIndex)}
                <button
                  type="button"
                  class={['berry-tree-combine-slot', { 'is-filled': !!slot.itemKey, selected: pickerSlotIndex === slot.slotIndex }]}
                  aria-pressed={pickerSlotIndex === slot.slotIndex}
                  title={slot.itemName ?? undefined}
                  onclick={() => openPicker(slot.slotIndex)}
                >
                  {#if slot.itemIconUrl}
                    <img class="berry-tree-slot-img" src={slot.itemIconUrl} alt="" width="32" height="32" />
                  {:else}
                    <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                  {/if}
                </button>
              {/each}
            </div>
            {#if bt.draftAlreadyAttempted}
              <div class="berry-tree-draft-warning-badge" role="status">
                <span>⚠️ {ui.alreadyAttemptedWarn}</span>
              </div>
            {/if}
            {#if bt.draftCostLabel}
              <p class="berry-tree-draft-cost-hint">{bt.draftCostLabel}</p>
            {/if}
            <div class="berry-tree-combine-actions">
              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--feed"
                data-action="tryBerryTreeCombination"
                disabled={!bt.canTryCombine}
              >{!bt.canTryCombine && bt.tryDisabledReason ? bt.tryDisabledReason : (queueDraftMode ? ui.queueCombineBtn : ui.tryBtn)}</button>
              <button type="button" class="miltank-farm-btn miltank-farm-btn--reroll" data-action="clearBerryCombineDraft">
                {ui.clearBtn}
              </button>
            </div>
            {#if pickerSlotIndex !== null}
              <div class="berry-tree-item-picker-panel">
                <div class="berry-tree-picker-panel-head">
                  <p class="berry-tree-picker-panel-title">
                    {ui.pickSlotTitle.replace('{slot}', String(pickerSlotIndex + 1))}
                  </p>
                  <button
                    type="button"
                    class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--reroll"
                    onclick={closePicker}
                  >{ui.closePickerBtn}</button>
                </div>
                <input
                  type="search"
                  class="berry-tree-picker-search"
                  placeholder={ui.searchItemsPlaceholder}
                  bind:value={pickerQuery}
                  aria-label={ui.searchItemsPlaceholder}
                />
                <div class="berry-tree-picker-filters">
                  <button
                    type="button"
                    class={['berry-tree-picker-filter', { 'is-active': pickerFilter === 'all' }]}
                    onclick={() => { pickerFilter = 'all'; }}
                  >{ui.pickerFilterAll}</button>
                  {#if pickerCategoryFlags.evo}
                    <button
                      type="button"
                      class={['berry-tree-picker-filter', { 'is-active': pickerFilter === 'evolution_stones' }]}
                      onclick={() => { pickerFilter = 'evolution_stones'; }}
                    >{ui.pickerFilterEvo}</button>
                  {/if}
                  {#if pickerCategoryFlags.combat}
                    <button
                      type="button"
                      class={['berry-tree-picker-filter', { 'is-active': pickerFilter === 'combat' }]}
                      onclick={() => { pickerFilter = 'combat'; }}
                    >{ui.pickerFilterCombat}</button>
                  {/if}
                  {#if pickerCategoryFlags.other}
                    <button
                      type="button"
                      class={['berry-tree-picker-filter', { 'is-active': pickerFilter === 'other' }]}
                      onclick={() => { pickerFilter = 'other'; }}
                    >{ui.pickerFilterOther}</button>
                  {/if}
                </div>
                <div class="berry-tree-item-picker">
                  {#if filteredPickerItems.length === 0}
                    <p class="berry-tree-empty">{ui.noEligibleItems}</p>
                  {:else}
                    <div class="berry-tree-picker-grid">
                      {#each filteredPickerItems as item (item.itemKey)}
                        <button
                          type="button"
                          class={['berry-tree-picker-tile', { 'is-placed': draftHasItem(item.itemKey), 'is-dead-end': itemCompletesFailedTrio(item.itemKey) }]}
                          title={item.displayName}
                          data-action="setBerryCombineSlot"
                          data-arg="{pickerSlotIndex}:{item.itemKey}"
                          onclick={(event) => afterPickSlot(event)}
                        >
                          {#if item.iconUrl}
                            <img src={item.iconUrl} alt="" class="item-sprite-img" width="32" height="32" />
                          {/if}
                          <span class="berry-tree-picker-qty">×{item.count}</span>
                          {#if itemInFailedTrio(item.itemKey) && !itemCompletesFailedTrio(item.itemKey)}
                            <span class="berry-tree-picker-miss" aria-hidden="true"></span>
                          {/if}
                        </button>
                      {/each}
                    </div>
                  {/if}
                </div>
              </div>
            {/if}
          {:else}
            <h3 class="berry-tree-subtitle">{ui.combineActiveTitle}</h3>
            <p class="berry-tree-hint">{ui.tryBtnInProgress}</p>
          {/if}
        </div>

        <div class="berry-tree-discover-side">
          {#if bt.combineInProgress}
            <div class="berry-tree-analyze-bar">
              <div class="berry-tree-analyze-bar-row">
                <p class="berry-tree-combine-progress-label">{bt.combineProgressLabel}</p>
                <div class="berry-tree-analyze-bar-icons">
                  {#each bt.combinePendingSlots as slot (slot.slotIndex)}
                    {#if slot.itemIconUrl}
                      <img src={slot.itemIconUrl} alt={slot.itemName ?? ''} width="22" height="22" title={slot.itemName ?? undefined} />
                    {:else}
                      <span class="berry-tree-mini-slot-empty">?</span>
                    {/if}
                  {/each}
                </div>
                <span class="berry-tree-combine-progress-pct">{bt.combineRemainingLabel ? `${bt.combineRemainingLabel} · ` : ''}{bt.combineProgressPct}%</span>
              </div>
              <div
                class="miltank-farm-bar berry-tree-combine-progress-bar"
                role="progressbar"
                aria-valuenow={bt.combineProgressPct}
                aria-valuemin="0"
                aria-valuemax="100"
                aria-label="{bt.combineProgressLabel ?? ui.combineProgress} — {bt.combineRemainingLabel ?? ''} {bt.combineProgressPct}%"
              >
                <div class="miltank-farm-bar-fill" style="width: {bt.combineProgressPct}%"></div>
              </div>
            </div>
          {/if}

          {#if bt.combineQueueLevel > 0 || bt.combineQueueUpgradeLabel}
            <div class="berry-tree-combine-queue-section" aria-label={ui.combineQueueSectionTitle}>
              <div class="berry-tree-combine-queue-head">
                <h3 class="berry-tree-subtitle">{ui.combineQueueSectionTitle}</h3>
                {#if bt.combineQueueCapacityLabel}
                  <span class="berry-tree-plant-queue-cap">{bt.combineQueueCapacityLabel}</span>
                {/if}
                {#if bt.combineQueueUpgradeLabel && bt.combineQueueLevel < bt.combineQueueMaxLevel}
                  <button
                    type="button"
                    class="berry-tree-queue-slot-btn"
                    onclick={purchaseCombineQueueUpgrade}
                    disabled={!bt.canPurchaseCombineQueueUpgrade}
                    title={combineQueueSlotTitle()}
                  >{ui.combineQueueAddSlot}{bt.combineQueueUpgradeCostLabel ? ` (${bt.combineQueueUpgradeCostLabel})` : ''}</button>
                {/if}
              </div>
              {#if bt.combineQueueLabel}
                <p class="berry-tree-combine-queue-label">{bt.combineQueueLabel}</p>
              {/if}
              {#if bt.combineQueueLevel === 0}
                <p class="berry-tree-hint">{ui.combineQueueUpgradeDesc}</p>
              {:else if bt.combineQueuePreview.length > 0 || queueRemainingSlots > 0}
                <div class="berry-tree-combine-queue-preview">
                  {#each bt.combineQueuePreview as queuedSlots, queueIndex (queueIndex)}
                    <div class="berry-tree-combine-queue-preview-row">
                      <span class="berry-tree-combine-queue-preview-index">{queueIndex + 1}</span>
                      <div class="berry-tree-combine-slots berry-tree-combine-slots--compact">
                        {#each queuedSlots as slot (`${queueIndex}-${slot.slotIndex}`)}
                          <div class={['berry-tree-combine-slot', { 'is-filled': !!slot.itemKey }]} title={slot.itemName ?? undefined}>
                            {#if slot.itemIconUrl}
                              <img class="berry-tree-slot-img" src={slot.itemIconUrl} alt="" width="24" height="24" />
                            {:else}
                              <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                            {/if}
                          </div>
                        {/each}
                      </div>
                    </div>
                  {/each}
                  {#each Array(queueRemainingSlots) as _, emptyIndex (`empty-${emptyIndex}`)}
                    <div class="berry-tree-combine-queue-preview-row berry-tree-combine-queue-preview-row--empty">
                      <span class="berry-tree-combine-queue-preview-index">{bt.combineQueuePreview.length + emptyIndex + 1}</span>
                      <div class="berry-tree-combine-slots berry-tree-combine-slots--compact">
                        {#each [0, 1, 2] as slotIndex (slotIndex)}
                          <div class="berry-tree-combine-slot">
                            <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                          </div>
                        {/each}
                      </div>
                    </div>
                  {/each}
                </div>
              {:else}
                <p class="berry-tree-hint">{ui.combineQueueEmptyHint}</p>
              {/if}
            </div>
          {/if}

          <div class="berry-tree-history-section">
            <div class="berry-tree-history-head">
              <h3 class="berry-tree-subtitle">{ui.historyTitle}</h3>
            </div>
            {#if visibleHistory.length > 0}
              <div class="berry-tree-history-list">
                {#each visibleHistory as entry, i (`${entry.timestamp}-${i}`)}
                  <div class={['berry-tree-history-row', { success: entry.success }]}>
                    <div class="berry-tree-history-slots">
                      {#each entry.submittedSlots as slot (slot.slotIndex)}
                        {#if slot.itemIconUrl}
                          <img
                            src={slot.itemIconUrl}
                            alt={slot.itemName ?? ''}
                            class="berry-tree-history-img"
                            width="22"
                            height="22"
                            {...itemTip(slot.itemName ?? '')}
                          />
                        {:else}
                          <span class="berry-tree-mini-slot-empty">?</span>
                        {/if}
                      {/each}
                    </div>
                    <div class="berry-tree-history-outcome">
                      <span class={['berry-tree-history-badge', {
                        'badge-unlocked': entry.outcomeType === 'unlocked',
                        'badge-revealed': entry.outcomeType === 'revealed',
                        'badge-none': entry.outcomeType === 'none',
                      }]}>
                        {entry.outcomeLabel}
                      </span>
                    </div>
                    <div class="berry-tree-history-meta">
                      <span class="berry-tree-history-time">{entry.timeAgoLabel}</span>
                      {#if draftSlotsEditable && entry.outcomeType !== 'none'}
                        <button
                          type="button"
                          class="berry-tree-history-reload-btn"
                          data-action="loadBerryCombineDraft"
                          data-arg={entry.serializedArg}
                          title={ui.reloadHistoryBtn}
                        >↺</button>
                      {/if}
                    </div>
                  </div>
                {/each}
              </div>
            {:else if bt.combineHistory.length === 0}
              <p class="berry-tree-hint">{bt.combineInProgress ? ui.historyPending : ui.historyEmpty}</p>
            {/if}
          </div>
        </div>
      </div>
    </section>
  {:else if activeTab === 'almanac'}
    <section class="berry-tree-panel" aria-label={ui.tabAlmanac}>
      <div class="berry-tree-almanac-subtabs sub-tabs-container" role="tablist">
        <button
          type="button"
          class={['sub-tab-btn', { active: almanacFilter === 'progress' }]}
          role="tab"
          aria-selected={almanacFilter === 'progress'}
          onclick={() => { almanacFilter = 'progress'; }}
        >{ui.almanacInProgress} ({almanacCounts.progress})</button>
        <button
          type="button"
          class={['sub-tab-btn', { active: almanacFilter === 'unlocked' }]}
          role="tab"
          aria-selected={almanacFilter === 'unlocked'}
          onclick={() => { almanacFilter = 'unlocked'; }}
        >{ui.almanacUnlocked} ({bt.unlockedCount}/{bt.totalCount})</button>
      </div>
      {#if bt.feticheTasteHint}
        <div class="berry-tree-taste-legend">
          <p class="berry-tree-fetiche-taste-short" title={bt.feticheTasteHint}>{ui.feticheTasteShort}:</p>
          <div class="berry-tree-taste-legend-items">
            {#each tasteLegend as item (item.taste)}
              <button
                type="button"
                class={[
                  'berry-tree-taste-legend-item',
                  tasteFilter === item.taste && 'is-active',
                  tasteFilter === item.taste && `fetiche-taste-${item.taste}`,
                ]}
                aria-pressed={tasteFilter === item.taste}
                title={item.label}
                onclick={() => { tasteFilter = tasteFilter === item.taste ? null : item.taste; }}
              >
                <span class="berry-tree-fetiche-taste fetiche-taste-{item.taste}">{item.mark}</span>
                <span class="berry-tree-taste-legend-label">{item.label}</span>
              </button>
            {/each}
          </div>
        </div>
      {/if}
      <div class={['berry-tree-almanac-grid', almanacFilter === 'unlocked' && 'is-unlocked']}>
        {#each almanacVisible as entry (entry.berryKey)}
          {#if entry.canPlant}
            <div
              class={[
                'berry-tree-almanac-card',
                'plantable',
                'unlocked',
                'miltank-farm-tooltip-host',
                entry.isActiveCrop && 'is-producing',
              ]}
              data-tooltip-variant="miltank-farm"
              title={entry.isActiveCrop ? ui.productionLabel : undefined}
              {...berryTooltipHandlers(entry)}
            >
              <div class="berry-tree-almanac-head">
                {#if entry.canQueue || entry.isQueued}
                  <button
                    type="button"
                    class={['berry-tree-almanac-berry-queue-btn', { queued: entry.isQueued }]}
                    data-action="setBerryPlantQueue"
                    data-arg={entry.berryKey}
                    title={ui.queueBerryBtn}
                    disabled={!entry.canQueue}
                  >
                    {#if entry.berryIconUrl}
                      <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
                    {/if}
                  </button>
                {:else if entry.berryIconUrl}
                  <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
                {/if}
                <h3 class="berry-tree-almanac-name">{entry.name}</h3>
                {#if entry.feticheTaste && tasteMark(entry.feticheTaste)}
                  <span class="berry-tree-almanac-head-meta">
                    <span class="berry-tree-fetiche-taste fetiche-taste-{entry.feticheTaste}" title={tasteLabel(entry.feticheTaste) ?? ''}>
                      {tasteMark(entry.feticheTaste)}
                    </span>
                  </span>
                {/if}
              </div>
              <button
                type="button"
                class="berry-tree-almanac-plant-trigger"
                data-action="confirmPlantBerryFromDex"
                data-arg={entry.berryKey}
              >
                <div class="berry-tree-recipe-slots">
                  {#each entry.recipeSlots as slot, i (entry.berryKey + '-' + i)}
                    <div class="berry-tree-recipe-slot" class:revealed={slot.revealed}>
                      {#if slot.revealed && slot.itemIconUrl}
                        <img
                          src={slot.itemIconUrl}
                          alt=""
                          width="24"
                          height="24"
                          {...itemTip(slot.itemName ?? '', slot.itemDescription ?? '')}
                        />
                      {:else}
                        <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                      {/if}
                    </div>
                  {/each}
                </div>
              </button>
            </div>
          {:else}
          <article
            class={[
              'berry-tree-almanac-card',
              'miltank-farm-tooltip-host',
              almanacGroup(entry) === 'progress' && 'is-progress',
              entry.isActiveCrop && 'is-producing',
            ]}
            data-tooltip-variant="miltank-farm"
            title={entry.isActiveCrop ? ui.productionLabel : undefined}
            {...berryTooltipHandlers(entry)}
            onclick={() => { if (almanacGroup(entry) === 'progress') useKnownHints(entry); }}
          >
            <div class="berry-tree-almanac-head">
              {#if entry.berryIconUrl}
                <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
              {/if}
              <h3 class="berry-tree-almanac-name">{entry.name}</h3>
              {#if almanacGroup(entry) === 'progress' || (entry.feticheTaste && tasteMark(entry.feticheTaste))}
                <span class="berry-tree-almanac-head-meta">
                  {#if almanacGroup(entry) === 'progress'}
                    <span class="berry-tree-hint-fraction">{revealedHintCount(entry)}/{entry.recipeSlots.length}</span>
                  {/if}
                  {#if entry.feticheTaste && tasteMark(entry.feticheTaste)}
                    <span class="berry-tree-fetiche-taste fetiche-taste-{entry.feticheTaste}" title={tasteLabel(entry.feticheTaste) ?? ''}>
                      {tasteMark(entry.feticheTaste)}
                    </span>
                  {/if}
                </span>
              {/if}
            </div>
            <div class="berry-tree-recipe-slots">
              {#each entry.recipeSlots as slot, i (entry.berryKey + '-' + i)}
                <div class="berry-tree-recipe-slot" class:revealed={slot.revealed}>
                  {#if slot.revealed && slot.itemIconUrl}
                    <img
                      src={slot.itemIconUrl}
                      alt=""
                      width="24"
                      height="24"
                      {...itemTip(slot.itemName ?? '', slot.itemDescription ?? '')}
                    />
                  {:else}
                    <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                  {/if}
                </div>
              {/each}
            </div>
          </article>
          {/if}
        {/each}
      </div>
    </section>
  {:else}
    <section class="berry-tree-panel" aria-label={ui.tabTree}>
      {#if bt.fertilizerActive && bt.boostRemainingLabel}
        <p class="berry-tree-boost-label">{bt.boostRemainingLabel}</p>
      {/if}
      {#if bt.fertilizerActive && bt.boostEffectDetailLabel}
        <p class="berry-tree-boost-detail">{bt.boostEffectDetailLabel}</p>
      {/if}
      <div class="berry-tree-status-row">
        <div class="berry-tree-status-col">
          {#if bt.activeCrop}
            <div class="berry-tree-crop-card">
              <div class="berry-tree-crop-head">
                {#if bt.activeCrop.berryIconUrl}
                  <img src={bt.activeCrop.berryIconUrl} alt="" width="40" height="40" />
                {/if}
                <div>
                  <strong>{bt.activeCrop.berryName}</strong>
                  <p>{ui.productionLabel}: {bt.activeCrop.productionRateLabel}</p>
                  <p>{ui.stockLabel}: {bt.activeCrop.storedQty}/{bt.activeCrop.stockCap}</p>
                </div>
              </div>
              <div class="berry-tree-combine-progress-card berry-tree-production-progress-card">
                <div class="berry-tree-combine-progress-head">
                  <p
                    class="berry-tree-combine-progress-label berry-tree-production-eta"
                    class:berry-tree-production-done={!!bt.activeCrop.productionDoneLabel}
                  >
                    {bt.activeCrop.productionDoneLabel ?? bt.activeCrop.productionEtaLabel ?? ui.productionLabel}
                  </p>
                  <span class="berry-tree-combine-progress-pct" aria-hidden="true">{bt.activeCrop.fillPct}%</span>
                </div>
                <div
                  class="miltank-farm-bar berry-tree-combine-progress-bar"
                  role="progressbar"
                  aria-valuenow={bt.activeCrop.fillPct}
                  aria-valuemin="0"
                  aria-valuemax="100"
                  aria-label="{(bt.activeCrop.productionDoneLabel ?? bt.activeCrop.productionEtaLabel ?? ui.productionLabel)} — {bt.activeCrop.fillPct}%"
                >
                  <div class="miltank-farm-bar-fill" style="width: {bt.activeCrop.fillPct}%"></div>
                </div>
              </div>
              <div class="berry-tree-crop-actions">
                <button
                  type="button"
                  class="miltank-farm-btn miltank-farm-btn--claim"
                  data-action="claimBerryTreeHarvest"
                  disabled={!bt.activeCrop.canClaim}
                >{ui.claimBtn}</button>
                <button
                  type="button"
                  class="miltank-farm-btn miltank-farm-btn--reroll"
                  data-action="cancelBerryTreeCrop"
                >{ui.cancelCropBtn}</button>
              </div>
            </div>
          {:else}
            <div class="berry-tree-crop-card">
              <div class="berry-tree-crop-head">
                <div>
                  <strong>{ui.treeIdle}</strong>
                  {#if bt.unlockedCount === 0}
                    <p class="berry-tree-empty">{ui.noBerryWelcome}</p>
                  {:else}
                    <p class="berry-tree-empty">{ui.noCrop}</p>
                  {/if}
                </div>
              </div>
              {#if bt.unlockedCount === 0}
                <button
                  type="button"
                  class="miltank-farm-btn miltank-farm-btn--feed"
                  onclick={() => { activeTab = 'discover'; }}
                >{ui.discoverBerryBtn}</button>
              {/if}
            </div>
          {/if}
        </div>

        <div class="berry-tree-status-col">
          {#if bt.plantQueueLevel > 0 || bt.plantQueueUpgradeLabel}
            <div class="berry-tree-plant-queue-section" aria-label={ui.plantQueueSectionTitle}>
              <div class="berry-tree-plant-queue-head">
                <h3 class="berry-tree-subtitle">{ui.plantQueueSectionTitle}</h3>
                {#if bt.plantQueueCapacityLabel}
                  <span class="berry-tree-plant-queue-cap">{bt.plantQueueCapacityLabel}</span>
                {/if}
                {#if bt.plantQueueUpgradeLabel && bt.plantQueueLevel < bt.plantQueueMaxLevel}
                  <button
                    type="button"
                    class="berry-tree-queue-slot-btn"
                    onclick={purchasePlantQueueUpgrade}
                    disabled={!bt.canPurchasePlantQueueUpgrade}
                    title={plantQueueSlotTitle()}
                  >{ui.plantQueueAddSlot}{bt.plantQueueUpgradeCostLabel ? ` (${bt.plantQueueUpgradeCostLabel})` : ''}</button>
                {/if}
              </div>
              {#if bt.plantQueueLevel > 0}
                {#if bt.plantQueuePreview.length > 0}
                  <div class="berry-tree-plant-queue-preview">
                    {#each bt.plantQueuePreview as entry, queueIndex (`${entry.berryKey}-${queueIndex}`)}
                      <div class="berry-tree-plant-queue-preview-row">
                        <span class="berry-tree-combine-queue-preview-index">{queueIndex + 1}</span>
                        <div class="berry-tree-plant-queue-chip" title={entry.displayName}>
                          {#if entry.iconUrl}
                            <img src={entry.iconUrl} alt="" width="28" height="28" />
                          {/if}
                          <span class="berry-tree-plant-queue-chip-name">{berryShortName(entry.displayName)}</span>
                        </div>
                      </div>
                    {/each}
                    {#each Array(plantQueueRemainingSlots) as _, emptyIndex (`plant-empty-${emptyIndex}`)}
                      <div class="berry-tree-plant-queue-preview-row berry-tree-combine-queue-preview-row--empty">
                        <span class="berry-tree-combine-queue-preview-index">{bt.plantQueuePreview.length + emptyIndex + 1}</span>
                        <div class="berry-tree-plant-queue-chip berry-tree-plant-queue-chip--empty">
                          <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                        </div>
                      </div>
                    {/each}
                  </div>
                {:else}
                  <p class="berry-tree-hint">{ui.plantQueueEmptyHint}</p>
                {/if}
                {#if bt.plantQueueBlockedReason}
                  <p class="berry-tree-hint berry-tree-queue-blocked">{bt.plantQueueBlockedReason}</p>
                {/if}
                {#if bt.canPlantFromQueue}
                  <div class="berry-tree-plant-queue-actions">
                    <button
                      type="button"
                      class="miltank-farm-btn miltank-farm-btn--feed"
                      data-action="plantBerryTreeFromQueue"
                    >{ui.queuePlantBtn}</button>
                  </div>
                {/if}
              {:else}
                <p class="berry-tree-hint">{ui.plantQueueUpgradeDesc}</p>
              {/if}
            </div>
          {/if}

          <h3 class="berry-tree-subtitle">{ui.boostActive}</h3>
          <div class="berry-tree-mulch-list">
            {#each bt.mulchOptions as mulch (mulch.mulchKey)}
              <button
                type="button"
                class="berry-tree-mulch-apply miltank-farm-tooltip-host"
                data-tooltip-variant="miltank-farm"
                data-action="applyBerryTreeFertilizer"
                data-arg={mulch.mulchKey}
                disabled={!mulch.canApply}
                title={mulch.blockedLabel ?? undefined}
                {...mulchHoverTooltip(mulch)}
              >
                <span class="berry-tree-mulch-apply-name">
                  {#if mulch.iconUrl}
                    <img src={mulch.iconUrl} alt="" width="20" height="20" />
                  {/if}
                  <span>{mulch.displayName} ×{mulch.owned}</span>
                </span>
                <span class="berry-tree-mulch-effect">{mulch.effectLabel}</span>
              </button>
            {/each}
          </div>
        </div>
      </div>

      {#if bt.unlockedCount > 0}
        <div class="berry-tree-section-head">
          <h3 class="berry-tree-subtitle">{ui.selectBerry}</h3>
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--reroll berry-tree-stock-btn"
            data-action="openBagBerriesFromBerryTree"
          >{ui.openBagBerries}</button>
        </div>
        <div class="berry-tree-plant-grid">
          {#each bt.plantOptions as opt (opt.berryKey)}
            <div class={['berry-tree-plant-row', { active: opt.isActive, queued: opt.isQueued }]}>
              <button
                type="button"
                class="berry-tree-plant-btn miltank-farm-tooltip-host"
                data-action="plantBerryTreeCrop"
                data-arg={opt.berryKey}
                data-tooltip-variant="miltank-farm"
                disabled={opt.isActive || !opt.canAffordIngredients}
                {...berryTooltipHandlers({
                  name: opt.displayName,
                  feticheTaste: opt.feticheTaste,
                  feticheStatEffect: opt.feticheStatEffect,
                  berryDescription: opt.berryDescription,
                })}
              >
                <span class="berry-tree-plant-line berry-tree-plant-line--id">
                  {#if opt.iconUrl}
                    <img src={opt.iconUrl} alt="" width="24" height="24" />
                  {/if}
                  <span class="berry-tree-plant-name berry-tree-plant-name--full">{opt.displayName}</span>
                  <span class="berry-tree-plant-name berry-tree-plant-name--short">{berryShortName(opt.displayName)}</span>
                  {#if opt.owned > 0}
                    <span class="berry-tree-plant-owned">×{opt.owned}</span>
                  {/if}
                </span>
                {#if (opt.feticheTaste && tasteMark(opt.feticheTaste)) || opt.feticheStatEffect}
                  <span class="berry-tree-plant-line berry-tree-plant-line--stats">
                    {#if opt.feticheTaste && tasteMark(opt.feticheTaste)}
                      <span class="berry-tree-fetiche-taste fetiche-taste-{opt.feticheTaste}" title={tasteLabel(opt.feticheTaste) ?? ''}>{tasteMark(opt.feticheTaste)}</span>
                    {/if}
                    {#if opt.feticheStatEffect}
                      <span class="berry-tree-fetiche-stat-hint" title={statHintTitle(opt)}>{@html statHintHtml(opt.feticheStatEffect)}</span>
                    {/if}
                  </span>
                {/if}
              </button>
              {#if opt.canQueue || opt.isQueued}
                <button
                  type="button"
                  class={['berry-tree-queue-add', { 'is-queued': opt.isQueued }]}
                  data-action="setBerryPlantQueue"
                  data-arg={opt.berryKey}
                  aria-label={ui.queueBerryBtn}
                  title={ui.queueBerryBtn}
                  disabled={!opt.canQueue}
                >
                  <span aria-hidden="true">+</span>
                  {#if opt.queuedCount > 1}<span class="berry-tree-queue-add-count">×{opt.queuedCount}</span>{/if}
                  <span class="berry-tree-queue-add-label">{ui.queueBerryBtn}</span>
                </button>
              {/if}
            </div>
          {/each}
        </div>
      {/if}
    </section>
  {/if}
</div>
